 auto parts=request("declare",source);parts.push_back({"include_header","","false",false});
 const auto run=execute_original_model_context(parts);assert(run.status==200);
 has(run.json,"\"model_type\":\"DeclareModel\"");has(run.json,"\"native_text_bytes\":"+serialize_embedding_workbench_string_json(expected));
 has(run.json,"\"model_before\":"+canonical+",\"model_after\":"+canonical);
 // Existing mined/map APIs keep deterministic map order and legacy formatting.
 const auto legacy=parse_original_context_declare_json(source);
 assert(legacy.rules.begin()->first=="absence");
 assert(abstract_declare(legacy,false).text=="\nThese are the constraints of the model:\nExistence: Z\nResponse: ('B', 'A')\n");
 DeclareModel empty_mined;assert(abstract_declare(empty_mined,false).text=="\nThese are the constraints of the model:\n");
 DeclareModel unknown;unknown.rules.clear();unknown.rules["unknown-family"]={{"literal","",false,1,1}};
 assert(abstract_declare(unknown,false).text=="\nThese are the constraints of the model:\nunknown-family: literal\n");
 rejects([]{(void)parse_original_context_ordered_declare_json(R"({"rules":[{"key":"existence","value":[]},{"key":{"native_bytes":"hex-v1","data":"6578697374656e6365"},"value":[]}]})");});
 rejects([]{(void)parse_original_context_ordered_declare_json(R"({"rules":{"existence":[],"exis\u0074ence":[]}})");});
 rejects([]{(void)parse_original_context_ordered_declare_json(R"({"rules":[{"key":"existence"}]})");});
